// XdgSurfaceConfigureEvent holds the arguments of the xdg_surface.configure event: suggest a surface change.
//
// The configure event marks the end of a configure sequence. A configure
// sequence is a set of one or more events configuring the state of the
// xdg_surface, including the final xdg_surface.configure event.
//
// Where applicable, xdg_surface surface roles will during a configure
// sequence extend this event as a latched state sent as events before the
// xdg_surface.configure event. Such events should be considered to make up
// a set of atomically applied configuration states, where the
// xdg_surface.configure commits the accumulated state.
//
// Clients should arrange their surface for the new states, and then send
// an ack_configure request with the serial sent in this configure event at
// some point before committing the new surface.
//
// If the client receives multiple configure events before it can respond
// to one, it is free to discard all but the last event it received.
type XdgSurfaceConfigureEvent struct {
	// Serial: serial of the configure event.
	Serial uint32
}

// SetConfigureHandler sets the callback for the configure event. Pass nil to remove it.
func (self *XdgSurface) SetConfigureHandler(h func(XdgSurfaceConfigureEvent)) { self.onConfigure = h }

// Dispatch implements wire.Object: it decodes one event and calls its handler.
func (self *XdgSurface) Dispatch(opcode uint16, r *wire.Reader) error {
	switch opcode {
	case 0: // configure
		var ev XdgSurfaceConfigureEvent
		ev.Serial = r.Uint()
		if err := r.Err(); err != nil {
			return err
		}
		if h := self.onConfigure; h != nil {
			h(ev)
		}
		return nil
	}
	return wire.UnknownEvent(self, opcode)
}

// Destroy sends the xdg_surface.destroy request: destroy the xdg_surface.
//
// Destroy the xdg_surface object. An xdg_surface must only be destroyed
// after its role object has been destroyed, otherwise
// a defunct_role_object error is raised.
//
// This is a destructor: the proxy must not be used afterwards.
func (self *XdgSurface) Destroy() {
	msg := self.Begin(0)
	msg.Done()
	self.MarkDestroyed()
}

// GetToplevel sends the xdg_surface.get_toplevel request: assign the xdg_toplevel surface role.
//
// This creates an xdg_toplevel object for the given xdg_surface and gives
// the associated wl_surface the xdg_toplevel role.
//
// See the documentation of xdg_toplevel for more details about what an
// xdg_toplevel is and how it is used.
//
// The new object has the same version as the receiver.
func (self *XdgSurface) GetToplevel() *XdgToplevel {
	msg := self.Begin(1)
	proxy_ := &XdgToplevel{}
	msg.NewObject(proxy_, self.Version())
	msg.Done()
	return proxy_
}

// GetPopup sends the xdg_surface.get_popup request: assign the xdg_popup surface role.
//
// This creates an xdg_popup object for the given xdg_surface and gives
// the associated wl_surface the xdg_popup role.
//
// If null is passed as a parent, a parent surface must be specified using
// some other protocol, before committing the initial state.
//
// See the documentation of xdg_popup for more details about what an
// xdg_popup is and how it is used.
//
// The new object has the same version as the receiver.
func (self *XdgSurface) GetPopup(parent *XdgSurface, positioner *XdgPositioner) *XdgPopup {
	msg := self.Begin(2)
	proxy_ := &XdgPopup{}
	msg.NewObject(proxy_, self.Version())
	var parentID uint32
	if parent != nil {
		parentID = parent.ID()
	}
	msg.Object(parentID)
	var positionerID uint32
	if positioner != nil {
		positionerID = positioner.ID()
	}
	msg.Object(positionerID)
	msg.Done()
	return proxy_
}

// SetWindowGeometry sends the xdg_surface.set_window_geometry request: set the new window geometry.
//
// The window geometry of a surface is its "visible bounds" from the
// user's perspective. Client-side decorations often have invisible
// portions like drop-shadows which should be ignored for the
// purposes of aligning, placing and constraining windows. Note that
// in some situations, compositors may clip rendering to the window
// geometry, so the client should avoid putting functional elements
// outside of it.
//
// The window geometry is double-buffered state, see wl_surface.commit.
//
// When maintaining a position, the compositor should treat the (x, y)
// coordinate of the window geometry as the top left corner of the window.
// A client changing the (x, y) window geometry coordinate should in
// general not alter the position of the window.
//
// Once the window geometry of the surface is set, it is not possible to
// unset it, and it will remain the same until set_window_geometry is
// called again, even if a new subsurface or buffer is attached.
//
// If never set, the value is the full bounds of the surface,
// including any subsurfaces. This updates dynamically on every
// commit. This unset is meant for extremely simple clients.
//
// The arguments are given in the surface-local coordinate space of
// the wl_surface associated with this xdg_surface, and may extend outside
// of the wl_surface itself to mark parts of the subsurface tree as part of
// the window geometry.
//
// When applied, the effective window geometry will be the set window
// geometry clamped to the bounding rectangle of the combined
// geometry of the surface of the xdg_surface and the associated
// subsurfaces.
//
// The effective geometry will not be recalculated unless a new call to
// set_window_geometry is done and the new pending surface state is
// subsequently applied.
//
// The width and height of the effective window geometry must be
// greater than zero. Setting an invalid size will raise an
// invalid_size error.
func (self *XdgSurface) SetWindowGeometry(x int32, y int32, width int32, height int32) {
	msg := self.Begin(3)
	msg.Int(x)
	msg.Int(y)
	msg.Int(width)
	msg.Int(height)
	msg.Done()
}

// AckConfigure sends the xdg_surface.ack_configure request: ack a configure event.
//
// When a configure event is received, if a client commits the
// surface in response to the configure event, then the client
// must make an ack_configure request sometime before the commit
// request, passing along the serial of the configure event.
//
// For instance, for toplevel surfaces the compositor might use this
// information to move a surface to the top left only when the client has
// drawn itself for the maximized or fullscreen state.
//
// If the client receives multiple configure events before it
// can respond to one, it only has to ack the last configure event.
// Acking a configure event that was never sent raises an invalid_serial
// error.
//
// A client is not required to commit immediately after sending
// an ack_configure request - it may even ack_configure several times
// before its next surface commit.
//
// A client may send multiple ack_configure requests before committing, but
// only the last request sent before a commit indicates which configure
// event the client really is responding to.
//
// Sending an ack_configure request consumes the serial number sent with
// the request, as well as serial numbers sent by all configure events
// sent on this xdg_surface prior to the configure event referenced by
// the committed serial.
//
// It is an error to issue multiple ack_configure requests referencing a
// serial from the same configure event, or to issue an ack_configure
// request referencing a serial from a configure event issued before the
// event identified by the last ack_configure request for the same
// xdg_surface. Doing so will raise an invalid_serial error.
func (self *XdgSurface) AckConfigure(serial uint32) {
	msg := self.Begin(4)
	msg.Uint(serial)
	msg.Done()
}

// XdgToplevel is the client proxy of the xdg_toplevel interface: toplevel surface.
